  function reset() { cnt.val = 0; forceUpdate(0) }

  return React.createElement('div', null,
    React.createElement('p', { style: { color: '#ccc' } }, '父组件 count: ' + cnt.val),
    React.createElement(Child, { count: cnt.val, onIncrement: increment, onReset: reset })
  )
