  var timerRef = React.useRef(null)

  React.useEffect(function() {
    console.log('⏰ 时钟已挂载')
    timerRef.current = setInterval(function() {
      setTime(new Date().toLocaleTimeString())
    }, 1000)

    // 清理函数：组件卸载时调用
    return function() {
      console.log('🔌 时钟已卸载，清理定时器')
      clearInterval(timerRef.current)
    }
  }, [])  // [] 表示只在挂载时执行一次

  return React.createElement('div', { style: { padding: '20px', background: '#2a2a3e', borderRadius: '12px', maxWidth: '300px', margin: '0 auto' } },
