    ),
    ['全部', '未完成', '已完成'].map(function(f) {
      return React.createElement('button', {
        key: f, onClick: function() { setFilter(f) },
        style: { padding: '4px 12px', border: '1px solid', borderColor: filter === f ? '#61dafb' : '#444', background: filter === f ? '#61dafb' : 'transparent', color: filter === f ? '#000' : '#ccc', borderRadius: '4px', cursor: 'pointer', marginRight: '4px', marginBottom: '12px', fontSize: '12px' }
      }, f)
    }),
    React.createElement('p', { style: { fontSize: '12px', color: '#888', marginBottom: '4px' } }, doneCount + '/' + todos.length + ' 已完成'),
    filtered.map(function(t) {
      return React.createElement('div', {
        key: t.id,
        onClick: function() { toggle(t.id) },
        style: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '6px 0', color: t.done ? '#666' : '#ccc', cursor: 'pointer', textDecoration: t.done ? 'line-through' : 'none' }
      },
        React.createElement('span', null, t.text),
        React.createElement('button', {
          onClick: function(e) { e.stopPropagation(); remove(t.id) },
          style: { background: 'transparent', color: '#ff4757', border: 'none', cursor: 'pointer', fontSize: '16px' }
        }, '✕')
      )
    })
  )
}

ReactDOM.createRoot(document.getElementById('root')).render(
  React.createElement(TodoApp)
)

